-- População inicial com os dados padrão do Roteiro de IA (incluindo dicas e recursos ricos)

SELECT setval('phases_id_seq', (SELECT COALESCE(MAX(id), 1) FROM phases));
SELECT setval('topic_groups_id_seq', (SELECT COALESCE(MAX(id), 1) FROM topic_groups));
SELECT setval('topics_id_seq', (SELECT COALESCE(MAX(id), 1) FROM topics));
SELECT setval('users_id_seq', (SELECT COALESCE(MAX(id), 1) FROM users));
